26	// ─── Hook ─────────────────────────────────────────────────────────────────────
27	
28	export function useAgencyCommissions(teamId: string | null) {
29	  const queryKey = ["agency_commissions", teamId];
30	
31	  const { data, isLoading, error } = useQuery({
32	    queryKey,
33	    queryFn: async (): Promise<{ commissions: AgencyCommission[]; totals: CommissionTotals }> => {
34	      if (!teamId) return { commissions: [], totals: { earned: 0, pending: 0, paid: 0 } };
35	      try {
36	        const { data, error } = await (supabase as any)
37	          .from("agency_commissions")
38	          .select("*, agency_placements(candidate_name)")
39	          .order("created_at", { ascending: false });
40	        if (error) throw error;
41	
42	        const rows = ((data ?? []) as any[]).map((row) => ({
43	          ...row,
44	          candidate_name: row.agency_placements?.candidate_name ?? null,
45	          agency_placements: undefined,
46	        })) as AgencyCommission[];
47	
48	        const totals: CommissionTotals = {
49	          earned: rows.reduce((s, r) => s + (r.amount ?? 0), 0),
50	          pending: rows
51	            .filter((r) => r.status === "pending")
52	            .reduce((s, r) => s + (r.amount ?? 0), 0),
53	          paid: rows
54	            .filter((r) => r.status === "paid")
55	            .reduce((s, r) => s + (r.amount ?? 0), 0),
56	        };
57	
58	        return { commissions: rows, totals };
59	      } catch {
60	        return { commissions: [], totals: { earned: 0, pending: 0, paid: 0 } };
61	      }
62	    },
63	    enabled: !!teamId,
64	    staleTime: 30_000,
65	  });
66	
67	  return {
68	    commissions: data?.commissions ?? [],
69	    totals: data?.totals ?? { earned: 0, pending: 0, paid: 0 },
70	    isLoading,
71	    error,
72	  };
73	}
